<?php
ob_start(); $pageTitle='Produk Toko'; require_once __DIR__.'/../includes/header.php';
if(!isBuyer()){redirect(BASE_URL.'/auth/login.php');}$store=getUserStore();if(!$store){redirect(BASE_URL.'/seller/');}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['delete'])){$id=(int)$_POST['delete'];if($conn){$sid=(int)$store['id'];$s=$conn->prepare('DELETE FROM products WHERE id=? AND store_id=?');$s->bind_param('ii',$id,$sid);$s->execute();}else unset($_SESSION['demo_seller_products'][$id]);setFlash('success','Produk dihapus dari toko.');redirect(BASE_URL.'/seller/products.php');}
$products=[];if($conn){$sid=(int)$store['id'];$r=$conn->query("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.store_id=$sid ORDER BY p.created_at DESC");while($r&&$p=$r->fetch_assoc())$products[]=$p;}else $products=array_values($_SESSION['demo_seller_products']??[]);
?>
<section class="section"><div class="container"><div class="page-header"><div><span class="eyebrow">TOKO: <?= sanitize($store['name']) ?></span><h1>Produk saya</h1></div><a class="btn btn-primary" href="<?= BASE_URL ?>/seller/product_form.php">＋ Tambah produk</a></div><?php if(!$products): ?><div class="empty-state"><span class="empty-icon">📦</span><h3>Tokomu masih kosong</h3><p>Unggah produk pertama dan mulai bagikan cerita barunya.</p><a href="<?= BASE_URL ?>/seller/product_form.php" class="btn btn-primary">Tambah produk</a></div><?php else: ?><div class="seller-product-list"><?php foreach($products as $p): ?><article class="seller-product"><div class="seller-product-image"><?php if(!empty($p['image'])): ?><img src="<?= BASE_URL ?>/uploads/products/<?= sanitize($p['image']) ?>" alt=""><?php else: ?>♻️<?php endif; ?></div><div class="seller-product-info"><span class="product-category"><?= sanitize($p['category_name']??'Preloved') ?></span><h3><?= sanitize($p['name']) ?></h3><strong><?= formatRupiah($p['price']) ?></strong><p class="text-muted">Stok <?= (int)$p['stock'] ?> · <?= statusLabel($p['status']) ?></p></div><div class="seller-product-actions"><a class="btn btn-outline btn-sm" href="<?= BASE_URL ?>/seller/product_form.php?id=<?= (int)$p['id'] ?>">Edit</a><form method="post"><button class="btn btn-danger btn-sm" name="delete" value="<?= (int)$p['id'] ?>" onclick="return confirm('Hapus produk ini?')">Hapus</button></form></div></article><?php endforeach; ?></div><?php endif; ?></div></section>
<?php require_once __DIR__.'/../includes/footer.php'; ?>
